// ContactPage.jsx
import React, { useState } from 'react';
import { Mail, Phone, Linkedin, Github, MapPin } from 'lucide-react';
import qrCodeImage from '../assets/LinkedinQRCode.png';
import resumePDF from '../assets/resume.pdf';
import emailjs from '@emailjs/browser';

export default function ContactPage() {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    message: '',
  });
  const [captchaVerified, setCaptchaVerified] = useState(false);
  const [captchaInput, setCaptchaInput] = useState('');
  const [generatedCaptcha, setGeneratedCaptcha] = useState('');
  const [captchaError, setCaptchaError] = useState('');
  const [formSubmitted, setFormSubmitted] = useState(false);

  React.useEffect(() => {
    generateCaptcha();
  }, []);

  const generateCaptcha = () => {
    const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
    let result = '';
    for (let i = 0; i < 6; i++) {
      result += chars.charAt(Math.floor(Math.random() * chars.length));
    }
    setGeneratedCaptcha(result);
    setCaptchaInput('');
    setCaptchaError('');
    setCaptchaVerified(false);
  };

  const verifyCaptcha = () => {
    if (captchaInput.toUpperCase() === generatedCaptcha) {
      setCaptchaVerified(true);
      setCaptchaError('');
    } else {
      setCaptchaError('Incorrect CAPTCHA. Please try again.');
      generateCaptcha();
    }
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!captchaVerified) {
      setCaptchaError('Please verify CAPTCHA first');
      return;
    }

    emailjs
      .send(
        process.env.REACT_APP_EMAILJS_SERVICE_ID,
        process.env.REACT_APP_EMAILJS_TEMPLATE_ID,
        formData,
        process.env.REACT_APP_EMAILJS_PUBLIC_KEY
      )
      .then(() => {
        setFormSubmitted(true);
        setFormData({ name: '', email: '', message: '' });
        setCaptchaInput('');
        setCaptchaVerified(false);
        generateCaptcha(); // fixed: was incorrectly passing the return value to setGeneratedCaptcha
      })
      .catch((err) => console.error('EmailJS error:', err));
  };

  const contactLinks = [
    {
      icon: Mail,
      label: 'Email',
      value: 'hubert@de-tournay.fr',
      href: 'mailto:hubert@de-tournay.fr',
    },
    {
      icon: Phone,
      label: 'Phone',
      value: '+33 6 22 34 02 18',
      href: 'tel:+33622340218',
    },
    {
      icon: Linkedin,
      label: 'LinkedIn',
      value: 'linkedin.com',
      href: 'https://www.linkedin.com/in/hubert-de-tournay/',
    },
    {
      icon: Github,
      label: 'GitHub',
      value: 'github.com/ragazoub',
      href: 'https://github.com/ragazoub',
    },
  ];

  return (
    <div className="contact-container">
      {/* Hero Section */}
      <section className="hero-section">
        <h1 className="hero-title">Let's Connect</h1>
        <p className="hero-description">
          I'm always interested in hearing about new projects and opportunities.
        </p>
        <div style={{ display: 'inline-flex', alignItems: 'center', gap: '12px', padding: '12px 16px', background: 'rgba(139, 92, 246, 0.1)', border: '1px solid var(--color-border)', borderRadius: '20px', color: 'var(--color-text-secondary)' }}>
          <MapPin size={20} color="var(--color-purple)" />
          <span>Lyon, France</span>
        </div>
      </section>

      {/* Main Content */}
      <div className="main-content">
        {/* Contact Links */}
        <section className="contact-links-section">
          <h2 className="section-title">Get In Touch</h2>
          <div className="contact-links-grid">
            {contactLinks.map((link, index) => {
              const Icon = link.icon;
              return (
                <a
                  key={index}
                  href={link.href}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="contact-link"
                >
                  <div className="icon-container">
                    <Icon size={28} color="var(--color-purple)" />
                  </div>
                  <h3 className="contact-link-label">{link.label}</h3>
                  <p className="contact-link-value">{link.value}</p>
                </a>
              );
            })}
          </div>
        </section>

        {/* QR Code and Form */}
        <div className="content-row">
          {/* QR Code */}
          <section className="qr-section">
            <h2 className="section-title">Connect on LinkedIn</h2>
            <div className="qr-container">
              <img
                src={qrCodeImage}
                alt="LinkedIn QR Code"
                className="qr-code"
              />
              <p className="qr-text">
                Scan to visit my LinkedIn profile
              </p>
            </div>
            <a
              href={resumePDF}
              target="_blank"
              rel="noopener noreferrer"
              className="resume-button"
            >
              View Resume
            </a>
          </section>

          {/* Contact Form */}
          <section className="form-section">
            <h2 className="section-title">Send Me a Message</h2>
            <form onSubmit={handleSubmit} className="form">
              <div className="form-group">
                <label htmlFor="name">Name</label>
                <input
                  id="name"
                  type="text"
                  name="name"
                  value={formData.name}
                  onChange={handleInputChange}
                  required
                />
              </div>

              <div className="form-group">
                <label htmlFor="email">Email</label>
                <input
                  id="email"
                  type="email"
                  name="email"
                  value={formData.email}
                  onChange={handleInputChange}
                  required
                />
              </div>

              <div className="form-group">
                <label htmlFor="message">Message</label>
                <textarea
                  id="message"
                  name="message"
                  value={formData.message}
                  onChange={handleInputChange}
                  required
                  rows="5"
                />
              </div>

              {/* CAPTCHA Section */}
              <div className="captcha-section">
                <label htmlFor="captcha-input">Verify you're human</label>
                <div className="captcha-box">
                  <div className="captcha-display" aria-hidden="true">
                    {generatedCaptcha}
                  </div>
                  <input
                    id="captcha-input"
                    type="text"
                    value={captchaInput}
                    onChange={(e) => {
                      setCaptchaInput(e.target.value);
                      setCaptchaError('');
                    }}
                    placeholder="Enter CAPTCHA"
                    className="captcha-input"
                  />
                  <button
                    type="button"
                    onClick={verifyCaptcha}
                    className="btn-small"
                  >
                    Verify
                  </button>
                </div>
                {captchaError && (
                  <p className="captcha-error">{captchaError}</p>
                )}
                {captchaVerified && (
                  <p className="captcha-success">✓ CAPTCHA verified</p>
                )}
              </div>

              <button
                type="submit"
                className="btn-primary submit-button"
              >
                {formSubmitted ? 'Message Sent! ✓' : 'Send Message'}
              </button>
            </form>
          </section>
        </div>
      </div>
    </div>
  );
}
